-- Notifications can be dismissed without being regenerated by the scheduler
-- (it re-inserts by id with ON CONFLICT DO NOTHING, so the row must stay).
ALTER TABLE notifications ADD COLUMN dismissed_at timestamptz;
CREATE INDEX notifications_owner_feed ON notifications(owner_id, created_at DESC) WHERE dismissed_at IS NULL;
CREATE INDEX audit_logs_owner_created ON audit_logs(owner_id, created_at DESC);
